local _, WFJ = ...
WFJ.Data.add("book", {
  ["e110f4617e655d67"] = { "Epilogo\n\n\"Ricoprire il cuore del carciofo di burro all'aglio e maionese. Accompagnare il pasto con una birra invecchiata e corposa.\"\n\nOra Drek'Thar è solo, con i suoi due cagnacci al fianco. Conquista la Frostwolf Relief Hut per avere un aiuto nella battaglia e distruggi Drek'Thar. Quando il generale cadrà, questa terra passerà finalmente al suo legittimo proprietario: i Piccatonante.", "." },
  ["e1131a7d4313ab8e"] = { "Ma Kegan era molto desideroso di parlare d'altro, in particolare della sua giovinezza a Lordaeron prima della caduta.\n\nProva ancora molto amore per quel regno perduto, anche se ora è in rovina, e morto.\n\nIl mio crescente affetto per Kegan mi diede pazienza mentre aspettavo i risultati degli esperimenti.", "." },
  ["e1351b127394107f"] = { "Sicuri di poter tenere testa alle bande da guerra dei troll, o perfino agli schivi elfi se fosse stato necessario, i signori della guerra Arathi decisero di costruire una possente città fortezza nelle regioni meridionali di Lordaeron. La città stato, chiamata Strom, divenne la capitale della nazione degli Arathi, Arathor. Mentre Arathor prosperava, umani da ogni parte del vasto continente si mettevano in viaggio verso sud, in cerca della protezione e della sicurezza di Strom.", "." },
  ["e150e8e6071fcfb5"] = { "⟦Peeling the Onion=Sbucciare la Cipolla⟧\nGuida pratica per smantellare i Piccatonante \n-Di Drek'Thar\n\nIn queste pagine troverai un patrimonio di conoscenze sulle tattiche di battaglia e sulla politica. Il soldato istruito è il soldato che si appoggia sulla spalla dell'esperienza. Che questo libro ti sia di guida nella battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["e166e8ea6c6a9acf"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI DEGLI UFFICIALI DELL'ALLEANZA</H1><BR/>\n<P align=\"center\">Parte 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">Gran Maresciallo</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Primo Maresciallo</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">Maresciallo</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Comandante</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Tenente Comandante</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["e1b3dbd4cff12518"] = { "Le due statue avrebbero vigilato sul passo verso le terre del sud, divenute vulcaniche sulla scia della presenza ardente di Ragnaros. Servivano sia da monito per chiunque volesse attaccare i regni dei nani, sia da ricordo del prezzo che i Ferroscuro avevano pagato per i loro crimini.", "." },
  ["e1cd32df9ecacb7d"] = { "Tra i due fu stretto un patto. Kel'Thuzad avrebbe ricevuto l'immortalità e un potere immenso in cambio della sua servitù al Re dei Lich. Il primo compito di Kel'Thuzad fu usare la sua ricchezza e la sua influenza a Lordaeron per fondare il Cult of the Damned. Il culto prometteva uguaglianza e vita eterna a tutti i suoi membri, purché giurassero fedeltà a Ner'zhul, il dio del Cult of the Damned.", "." },
  ["e1eeb9417569935e"] = { "Generale Turalyon\n\nGià luogotenente di lord Anduin Lothar. Cavaliere della ⟦Silver Hand=Mano d'Argento⟧. Gran generale della Spedizione dell'⟦Alliance=Alleanza⟧ che marciò su Draenor, il mondo natale degli orchi. Presunto morto.\n\nEsarus thar no'Darador' - Per il Sangue e per l'Onore noi serviamo. \nFosti la mano destra della giustizia e della virtù, vecchio amico. Il tuo nome sarà sempre onorato nelle nostre sale.\n\n- Lord Uther il Portatore di Luce - Cavaliere della ⟦Silver Hand=Mano d'Argento⟧", "." },
})
